def test_parse_hookimpl_override() -> None:
    class MyPluginManager(PluginManager):
        def parse_hookimpl_opts(self, module_or_class, name):
            opts = PluginManager.parse_hookimpl_opts(self, module_or_class, name)
            if opts is None and name.startswith("x1"):
                opts = {}  # type: ignore[assignment]
            return opts

    class Plugin:
        def x1meth(self):
            pass  # pragma: no cover

        @hookimpl(hookwrapper=True, tryfirst=True)
        def x1meth2(self):
            yield  # pragma: no cover

        @hookimpl(wrapper=True, trylast=True)
        def x1meth3(self):
            return (yield)  # pragma: no cover

    class Spec:
        @hookspec
        def x1meth(self):
            pass  # pragma: no cover

        @hookspec
        def x1meth2(self):
            pass  # pragma: no cover

        @hookspec
        def x1meth3(self):
            pass  # pragma: no cover

    pm = MyPluginManager(hookspec.project_name)
    pm.register(Plugin())
    pm.add_hookspecs(Spec)

    hookimpls = pm.hook.x1meth.get_hookimpls()
    assert len(hookimpls) == 1
    assert not hookimpls[0].hookwrapper
    assert not hookimpls[0].wrapper
    assert not hookimpls[0].tryfirst
    assert not hookimpls[0].trylast
    assert not hookimpls[0].optionalhook

    hookimpls = pm.hook.x1meth2.get_hookimpls()
    assert len(hookimpls) == 1
    assert hookimpls[0].hookwrapper
    assert not hookimpls[0].wrapper
    assert hookimpls[0].tryfirst

    hookimpls = pm.hook.x1meth3.get_hookimpls()
    assert len(hookimpls) == 1
    assert not hookimpls[0].hookwrapper
    assert hookimpls[0].wrapper
    assert not hookimpls[0].tryfirst
    assert hookimpls[0].trylast

@pytest.mark.parametrize("historic", [False, True])
def test_register_while_calling(
    pm: PluginManager,
    historic: bool,
) -> None:
    """Test that registering an impl of a hook while it is being called does
    not affect the call itself, only later calls.

    For historic hooks however, the hook is called immediately on registration.

    Regression test for #438.
    """
    hookspec = HookspecMarker("example")

    class Hooks:
        @hookspec(historic=historic)
        def configure(self) -> int:
            raise NotImplementedError()

    class Plugin1:
        @hookimpl
        def configure(self) -> int:
            return 1

    class Plugin2:
        def __init__(self) -> None:
            self.already_registered = False

        @hookimpl
        def configure(self) -> int:
            if not self.already_registered:
                pm.register(Plugin4())
                pm.register(Plugin5())
                pm.register(Plugin6())
                self.already_registered = True
            return 2

    class Plugin3:
        @hookimpl
        def configure(self) -> int:
            return 3

    class Plugin4:
        @hookimpl(tryfirst=True)
        def configure(self) -> int:
            return 4

    class Plugin5:
        @hookimpl()
        def configure(self) -> int:
            return 5

    class Plugin6:
        @hookimpl(trylast=True)
        def configure(self) -> int:
            return 6

    pm.add_hookspecs(Hooks)
    pm.register(Plugin1())
    pm.register(Plugin2())
    pm.register(Plugin3())

    if not historic:
        result = pm.hook.configure()
        assert result == [3, 2, 1]
        result = pm.hook.configure()
        assert result == [4, 5, 3, 2, 1, 6]
    else:
        result = []
        pm.hook.configure.call_historic(result.append)
        assert result == [4, 5, 6, 3, 2, 1]
        result = []
        pm.hook.configure.call_historic(result.append)
        assert result == [4, 5, 3, 2, 1, 6]

def test_get_hookcallers_no_duplicates(pm: PluginManager) -> None:
    """Verify that get_hookcallers does not return duplicate HookCaller
    entries when a plugin has multiple hookimpls on the same hook (#431)."""

    class Api:
        @hookspec
        def hello(self, arg: object) -> object: ...

        @hookspec
        def goodbye(self, arg: object) -> object: ...

    pm.add_hookspecs(Api)

    class Plugin:
        @hookimpl
        def hello(self, arg: object) -> int:
            return arg + 1  # type: ignore[operator]

        @hookimpl(specname="hello")
        def hello_again(self, arg: object) -> int:
            return arg + 100  # type: ignore[operator]

        @hookimpl
        def goodbye(self, arg: object) -> int:
            return arg + 200  # type: ignore[operator]

    plugin = Plugin()
    pm.register(plugin)

    hookcallers = pm.get_hookcallers(plugin)
    assert hookcallers is not None
    # Should return 2 unique callers (hello + goodbye), not 3.
    assert len(hookcallers) == 2
    caller_names = {hc.name for hc in hookcallers}
    assert caller_names == {"hello", "goodbye"}
    # Both hello impls are still wired up, and each caller works.
    assert pm.hook.hello(arg=1) == [101, 2]
    assert pm.hook.goodbye(arg=1) == [201]
